package main

import ("bufio";"fmt";"os";"strconv";"strings")

func main(){
    in:=bufio.NewReader(os.Stdin)
    fmt.Print("Enter two integers: ")
    line,err:=in.ReadString('\n'); if err!=nil {fmt.Fprintln(os.Stderr,"input error:",err);os.Exit(1)}
    fields:=strings.Fields(line); if len(fields)!=2 {fmt.Fprintln(os.Stderr,"expected two integers");os.Exit(1)}
    a,err:=strconv.Atoi(fields[0]);if err!=nil {fmt.Fprintln(os.Stderr,"invalid first integer");os.Exit(1)}
    b,err:=strconv.Atoi(fields[1]);if err!=nil {fmt.Fprintln(os.Stderr,"invalid second integer");os.Exit(1)}
    fmt.Println("sum:",a+b)
}
